function randomId(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;}
function Mark({small=false}:{small?:boolean}){return <span className={'brand-mark '+(small?'small':'')}><AudioLines size={small?20:28} strokeWidth={2}/></span>;}
function Ring({value,size=146,label='Readiness score',light=false}:{value:number;size?:number;label?:string;light?:boolean}){return <div className={'score-ring '+(light?'light':'')} style={{width:size,height:size}} role="img" aria-label={`${label}: ${value} out of 100`}><svg viewBox="0 0 160 160"><circle className="ring-track" cx="80" cy="80" r="68"/><circle className="ring-value" cx="80" cy="80" r="68" strokeDasharray={`${value*4.2726} 427.26`} transform="rotate(-90 80 80)"/></svg><div><strong>{value}<span>/100</span></strong><small>{label}</small></div></div>;}
function Speak({text,lang,label}:{text:string;lang:Lang;label?:string}){const[active,setActive]=useState(false);return <button className={'speak-btn '+(active?'active':'')} aria-label={label|| (lang==='hi'?'सुनें':'Read aloud')} title={lang==='hi'?'सुनें':'Read aloud'} onClick={()=>{if(active){speech.stopSpeaking();setActive(false);}else{if(!('speechSynthesis'in window)){toast('Read aloud is unavailable in this browser.');return;}setActive(true);speech.speak(text,lang,()=>setActive(false));}}}>{active?<VolumeX size={17}/>:<Volume2 size={17}/>}</button>;}
function NavButton({active,icon:Icon,label,onClick}:{active:boolean;icon:any;label:string;onClick:()=>void}){const{setOpenMobile}=useSidebar();return <button className={'nav-item '+(active?'selected':'')} onClick={()=>{onClick();setOpenMobile(false);}}><Icon size={20}/><span>{label}</span>{active&&<span className="nav-dot"/>}</button>;}
function Stat({icon:Icon,label,value,note}:{icon:any;label:string;value:string;note:string}){return <div className="stat"><span className="stat-icon"><Icon size={20}/></span><div><small>{label}</small><strong>{value}</strong><p>{note}</p></div></div>;}
function Metric({label,value,note}:{label:string;value:number|null;note?:string}){return <div className="metric"><div><span>{label}</span><strong>{value===null?'—':`${value}/100`}</strong></div><Progress value={value||0} aria-label={label}/>{note&&<p>{note}</p>}</div>;}
